function load(){let primary=null;try{primary=JSON.parse(localStorage.getItem(SAVE)||'null')}catch(e){console.warn('メインセーブ破損:',e)}if(validSave(primary))return primary;
 for(const key of [SAVE+'_recovery',SAVE+'_backup']){try{let copy=JSON.parse(localStorage.getItem(key)||'null');if(validSave(copy)){window.__forgeRecoveredFrom=key;return copy}}catch(e){console.warn('バックアップ検証失敗:',key,e)}}return null}
function save(){try{let text=JSON.stringify(state.snapshot()),now=Date.now();if(!text||text.length>2e6)throw Error('セーブサイズ制限');
 if(now-lastBackingAt>=60000){const previous=localStorage.getItem(SAVE);if(previous){let old;try{old=JSON.parse(previous)}catch(_){}if(validSave(old))localStorage.setItem(SAVE+'_recovery',previous)}lastBackingAt=now}
 localStorage.setItem(SAVE,text);return true}catch(e){console.warn('保存失敗',e);note('保存できません。設定からセーブを書き出してください。');return false}}
function restore(){let old=load();state=new ForgeEngine(window.FORGE_DATA,old);if(window.__forgeRecoveredFrom){let key=window.__forgeRecoveredFrom;console.warn('バックアップから回復:',key);setTimeout(()=>note('保存データに問題があったため、バックアップから復元しました。必要なら設定で書き出してください。'),1000)}if(old){let dt=Math.min(24*3600,Math.max(0,(Date.now()-Number(old.lastSave||Date.now()))/1000));if(dt>=30){state.offline(dt);note(`おかえりなさい！ お休み中の${Math.floor(dt/60)}分の報酬を受け取りました。`)}}return !!old}
function getAvailable(){let s=state.state,peak=H.from(s.bestE),e=state.data.exploration[0];return {guide:true,automation:true,achievements:true,constellations:peak.gte('1e4')||s.unlockedTier>=1,research:peak.gte('1e4')||s.unlockedTier>=1,workshop:state.workshop.stage>=1,prestige:peak.gte('1e7')||s.unlockedTier>=1||(s.grandCycle?.bestTier||0)>0,skills:s.unlockedTier>=1,dimension:s.unlockedTier>=1,explore:state.canExplore(e)||Object.values(s.exploration).some(Boolean),civil:state.data.civilizations.some(x=>state.civUnlocked(x)),laws:s.unlockedTier>=6,challenge:s.unlockedTier>=1,pets:peak.gte('1e5')||s.unlockedTier>=1||state.petCollection().lifetimePulls>0,celestial:state.cosmosAvailable()}}
