function renderPets(){
 const pet=state.petCollection(),def=window.HitotsubuPets.rarities,c1=state.petCost(1),c10=state.petCost(10);
 const img=i=>`<img loading="lazy" decoding="async" src="assets/pets/${def[i].id}.webp" alt="${safe(def[i].pet)}" />`;
 const pct=v=>{let x=v*100;return (x<.1?x.toFixed(3):x<1?x.toFixed(2):x<10?x.toFixed(1):x.toLocaleString('ja-JP',{maximumFractionDigits:1}))+'%'};
 const card=(i,count,plus=null)=>{const d=def[i],name=plus!==null?`ゴッド＋${plus}`:d.name,src=img(i),bonus=plus===null?window.Huge.from(d.prod):window.Huge.from(d.prod).mul(window.Huge.from(6).pow(plus));
 const bonusText=plus===null?pct(d.prod):'300% × 6^'+plus;
 const next=plus!==null?'ゴッド＋'+(plus+1):i===5?'ゴッド＋1':def[i+1].name;
 return `<article class="pet-card" style="--pet-color:${d.color}"><div class="pet-art">${src}</div><div class="pet-description"><strong>${safe(d.pet)}</strong><span class="pet-rank">${name}</span><small>所持 ${count.toLocaleString('ja-JP')}体</small><small>1体の自動生産補正 ＋${bonusText}（ペット転生倍率前）</small></div><button type="button" class="pet-merge" data-pet-merge="${i}" ${plus!==null?`data-pet-plus="${plus}"`:''} ${count<5?'disabled':''}>5体で合成 → ${next}</button>${count>=10?`<button type="button" class="pet-merge pet-merge-all" data-pet-merge-all="${i}" ${plus!==null?`data-pet-plus="${plus}"`:''}>${Math.floor(count/5)}回分まとめて合成</button>`:''}</article>`;};
 return `<div class="side-body pet-page"><span class="eyebrow">ペット / ずかん</span><h3>ちいさな仲間たち</h3><p class="tiny">手に入れたペットは通常の転生では消えません。ガチャはプレイ中に集めたエネルギーだけで利用できます。現金・有料通貨はありません。</p>
 <section class="pet-summary"><div><small>ペットによる自動生産倍率</small><strong>×${fmt(state.petBonus('prod'))}</strong></div><div><small>ペット転生</small><strong>${pet.rebirths}回</strong></div><div><small>今回のガチャ回数</small><strong>${pet.pulls.toLocaleString('ja-JP')}回</strong></div></section>
 <section class="pet-draw"><h4>ペットを迎える</h4><p class="tiny">1回ごとに価格が1.2%上がります。10連は単発を10回引くのと同じ費用です。ガチャをしなくても設備・自動化・転生で進められます。大量のペットを集めた場合は補正の伸びが少し緩やかになります。ペット転生の強化分は毎回2倍です。</p><div class="pet-draw-actions"><button data-pet-pull="1" ${!c1||!state.amount('E').gte(c1)?'disabled':''}>1回 <small>${c1?fmt(c1):'上限'} E</small></button><button data-pet-pull="10" ${!c10||!state.amount('E').gte(c10)?'disabled':''}>10連 <small>${c10?fmt(c10):'上限'} E</small></button></div><div class="pet-pity" aria-label="ゴッド保証の進捗"><div><span>ゴッド保証まで</span><strong>あと ${window.HitotsubuPets.pityLimit-pet.sinceGod} 回以内</strong></div><div class="pet-pity-track"><span style="width:${Math.min(100,100*pet.sinceGod/window.HitotsubuPets.pityLimit)}%"></span></div><small>ゴッドが出ないまま200回目を迎えると、200回目はゴッド確定。通常の排出でもゴッドが出れば回数を数え直します。10連内でも適用。</small></div><details><summary>排出確率と保証ルールを見る</summary><div class="pet-odds">${def.map(x=>`<div><span>${x.name}</span><strong>${x.chance}%</strong></div>`).join('')}</div><p class="tiny">上記は保証が発動しない通常の抽選確率です。保証対象の回はゴッド100%。10連特別確定枠はありません。ガチャはエネルギーを消費する任意の機能です。</p></details></section>
 <h4 class="pet-section-title">ペット図鑑と合成</h4><p class="tiny">同じランクの5体で次のランクの1体に合成。まとめて合成は表示したランクだけに作用し、勝手に上位まで連続合成しません。ゴッドは＋1、＋2…と成長します。</p><div class="pet-grid">${def.map((d,i)=>card(i,pet.counts[i])).join('')}${Object.keys(pet.godPlus).map(Number).filter(n=>(pet.godPlus[n]||0)>0).sort((a,b)=>a-b).map(n=>card(5,pet.godPlus[n],n)).join('')}</div>
 <section class="pet-prestige"><h4>ペット転生</h4><p>ゴッド＋5の作成で解放。ペットの所持数とガチャ回数・保証の進捗が初期化されます。設備・通常転生・資源・実績は残ります。</p><p class="tiny">転生するたびに、その後集めるペットの強化分が2倍、4倍、8倍…になります。ペット未所持なら倍率は×1です。</p><button data-pet-rebirth="1" ${!pet.unlocked?'disabled':''}>${pet.unlocked?'ペット転生を実行する':'ゴッド＋5で解放'}</button></section></div>`;
}
function showPetResults(result){const names=window.HitotsubuPets.rarities,counts={};result.hits.forEach(n=>{counts[n]=(counts[n]||0)+1});modal(`<span class="eyebrow">NEW FRIENDS</span><h2 id="modal-title">新しい仲間が来ました</h2><div class="pet-result-grid">${Object.entries(counts).map(([id,num])=>{const r=names[id];return `<div class="pet-result"><img src="assets/pets/${r.id}.webp" alt="${safe(r.pet)}"><strong>${safe(r.pet)}</strong><small>${r.name} ×${num}</small></div>`}).join('')}</div><p>使用したエネルギー：${fmt(result.cost)} E</p><button class="action" data-action="close-modal">確認する</button>`,'pet-result');}
function showPetRebirthConfirm(){const p=state.petCollection();modal(`<span class="eyebrow">PET REBIRTH</span><h2 id="modal-title">ペット転生をしますか？</h2><p>すべてのペットを失い、ガチャ回数・価格・ゴッド保証の進捗が初期化されます。通常ゲームの進行は変わりません。</p><p><strong>現在のペット強化係数 ×${fmt(window.Huge.from(2).pow(p.rebirths))} → 転生後の係数 ×${fmt(window.Huge.from(2).pow(p.rebirths+1))}</strong></p><p>この操作は元に戻せません。</p><button class="action" data-pet-confirm="1">ペットだけ転生する</button><button class="action secondary" data-action="close-modal">キャンセル</button>`,'pet-rebirth');}

function renderPanel(){let panelRoot=$('side-content');let scrollNode=panelRoot.closest('.right-panel');let scrollTop=scrollNode?.scrollTop||0;let opened=[...panelRoot.querySelectorAll('details[open]')].map(x=>x.querySelector('summary')?.textContent);let valid={guide:renderGuide,automation:renderAutomation,achievements:renderAchievements,workshop:renderWorkshop,constellations:renderConstellations,research:renderResearch,prestige:renderPrestige,skills:renderSkills,explore:renderExplore,civil:renderCiv,laws:renderLaws,challenge:renderChallenges,celestial:()=>window.ForgeStellarUI.render(),pets:renderPets};panelRoot.innerHTML=(valid[tab]||renderGuide)()+'';if(scrollNode&&scrollTop)scrollNode.scrollTop=scrollTop;for(const el of panelRoot.querySelectorAll('details')){if(opened.includes(el.querySelector('summary')?.textContent))el.open=true}document.querySelectorAll('.tab').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab)});}
function render(rebuildPanel=true){updateVisibility(true);renderTop();renderFacilities();renderMission();if(rebuildPanel)renderPanel();window.ForgeImmersion?.update();window.ForgeBeyondVisual?.update(state);applyPreferences();}
function tapFloat(){if(!state.state.settings.effects)return;let now=performance.now();if(now-lastCoreFloat<75)return;lastCoreFloat=now;let e=document.createElement('span');e.className='tap-float';e.textContent='+'+fmt(state.tapPower());e.style.left=(47+Math.random()*14)+'%';$('tap-floats').appendChild(e);setTimeout(()=>e.remove(),950);if($('tap-floats').childElementCount>8)$('tap-floats').firstElementChild?.remove()}
function flash(){window.ForgeImmersion?.tap();if(!state.state.settings.effects)return;const core=$('core');if(core.animate)core.animate([{transform:'scale(1)'},{transform:'scale(.92)'},{transform:'scale(1.045)'},{transform:'scale(1)'}],{duration:240});tapFloat()}
function miniStop(){if(!mini.running)return;let elapsed=(performance.now()-mini.start)/1000,phase=(elapsed*0.74)%2,pos=phase<=1?phase:2-phase,acc=Math.max(0,1-Math.abs(pos-.5)*2);mini.hits.push(acc);mini.round++;if(mini.round>=3){mini.running=false;let avg=mini.hits.reduce((a,b)=>a+b,0)/3;if(state.playMini(avg)){window.ForgeImmersion?.mini();note('軌道シンクロ成功！ 精度 '+Math.round(avg*100)+'%。追加エネルギーを獲得！');}mini.hits=[]}else mini.start=performance.now();render()}
function animateMini(){if(mini.running){let e=$('mini-needle');if(e){let p=((performance.now()-mini.start)/1000*.74)%2;e.style.left=((p<=1?p:2-p)*100)+'%'}}requestAnimationFrame(animateMini)}
function exportSave(){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(state.snapshot(),null,2)],{type:'application/json'}));a.download='hitotsubu-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);note('セーブファイルを保存しました')}
async function importSave(file){try{if(!file||file.size>2e6)throw Error('ファイルサイズが大きすぎます');let parsed=JSON.parse(await file.text());if(!validSave(parsed))throw Error('データの形式または計算値が不正です');let replacement=new ForgeEngine(window.FORGE_DATA,parsed);replacement.production();replacement.tapPower();try{localStorage.setItem(SAVE+'_backup',JSON.stringify(state.snapshot()))}catch(_){}const previousState=state;state=replacement;if(!save()){state=previousState;throw Error('保存先に書き込めませんでした。容量を確認してください')}window.ForgeImmersion?.reload();tab='guide';render();note('セーブを読み込みました。以前の状態は自動バックアップに保持しています')}catch(e){note('読み込みに失敗：'+e.message)}}
let previouslyFocused=null;function modal(html,type){previouslyFocused=document.activeElement;modalMode=type;$('modal-content').innerHTML=html;$('overlay').hidden=false;document.body.style.overflow='hidden';$('overlay').querySelector('.modal-close').focus()}
function closeModal(){modalMode='';$('overlay').hidden=true;document.body.style.overflow='';if(previouslyFocused?.isConnected)previouslyFocused.focus({preventScroll:true});previouslyFocused=null;}
function showIntro(){startTour('intro')}
function completeIntro(){finishTour()}
function showHelp(){modal(`<span class="eyebrow">使い方</span><h2 id="modal-title">ひとつぶの遊び方</h2><p>粒を押してエネルギーを集め、設備を設置すると生産が続きます。操作に慣れたら自動化を進めて、合成や天体づくりへ広げていきましょう。</p><div class="glossary"><div><strong>エネルギー</strong><span>設備や研究を購入するための資源です。</span></div><div><strong>自動化</strong><span>作業を手動で練習してから解放します。自動実行では経験値は増えません。装置配置は設計図に保存した通りに再建します。</span></div><div><strong>実績</strong><span>達成した目標の記録です。専用タブからいつでも確認できます。</span></div><div><strong>再誕</strong><span>設備などを整理して上位の通貨を得ます。T1〜T15のどの転生でもT0へ戻ります。通貨・設備は初期化されますが、永続倍率・設計図・習得した自動化を持ち越せます。突破済みの階層は再建でき、再建では永続倍率は増えません。</span></div><div><strong>セーブ</strong><span>自動的に端末へ保存します。別端末へ移す場合は、設定からデータを書き出してください。</span></div></div><div class="modal-actions"><button class="action secondary" data-action="close-modal">閉じる</button><button class="action" data-action="start-walkthrough">画面の案内を再生する</button></div>`,'help')}
function tourTargetFor(step){let compact=window.matchMedia('(max-width:760px)').matches;if(step.where==='automation'&&compact&&step.target==='#automation-dashboard')return document.querySelector('[data-mobile="automation"]');if(step.where==='achievements'&&compact&&step.target==='#achievement-dashboard')return document.querySelector('[data-mobile="achievements"]');return document.querySelector(step.target)}
function startTour(mode='intro'){if(!$('overlay').hidden)closeModal();tourMode=mode;tourIndex=0;tourActive=true;$('walkthrough').hidden=false;showTourStep()}
function showTourStep(){if(!tourActive)return;let steps=WALKTHROUGH[tourMode],step=steps[tourIndex];if(!step){finishTour();return}goto(step.where);$('walkthrough-index').textContent=`${String(tourIndex+1).padStart(2,'0')} / ${String(steps.length).padStart(2,'0')}`;$('walkthrough-heading').textContent=step.title;$('walkthrough-description').textContent=step.text;$('walkthrough').querySelector('.walkthrough-next').textContent=tourIndex===steps.length-1?'遊びに戻る':'次へ →';requestAnimationFrame(()=>{let target=tourTargetFor(step);if(target&&!target.getClientRects().length){target=document.querySelector(step.where==='equipment'?'#equipment-panel':'#menu-panel')}if(target){target.scrollIntoView({block:'nearest',behavior:'instant'});}requestAnimationFrame(placeTour)})}
function placeTour(){if(!tourActive)return;let step=WALKTHROUGH[tourMode][tourIndex],el=tourTargetFor(step);if(!el||!el.getClientRects().length){$('walkthrough-outline').style.opacity=0;return;}let r=el.getBoundingClientRect(),pad=7;let x=Math.max(5,r.left-pad),y=Math.max(5,r.top-pad),right=Math.min(innerWidth-5,r.right+pad),bottom=Math.min(innerHeight-5,r.bottom+pad);let o=$('walkthrough-outline');Object.assign(o.style,{left:x+'px',top:y+'px',width:(right-x)+'px',height:(bottom-y)+'px',opacity:1});let panel=$('walkthrough-panel'),wide=innerWidth>760,ph=panel.offsetHeight||200;panel.style.left=wide?Math.max(12,Math.min(innerWidth-panel.offsetWidth-12,right+16))+'px':'12px';panel.style.right=wide?'auto':'12px';let above=y-ph-14,below=bottom+14;panel.style.top=(below+ph<innerHeight-8?below:above>8?above:Math.max(8,innerHeight-ph-16))+'px';}
function advanceTour(){tourIndex++;if(tourIndex>=WALKTHROUGH[tourMode].length)finishTour();else showTourStep()}
function finishTour(){if(!tourActive)return;let mode=tourMode;tourActive=false;$('walkthrough').hidden=true;try{localStorage.setItem(mode==='intro'?INTRO:AUTO_INTRO,'done')}catch(_){}goto('core');if(mode==='intro'&&!state.state.taps)note('中央の粒を押して、はじめましょう。')}
function checkAutomationTour(){if(!state||autoTipShown||tourActive||state.workshop.stage<2)return;autoTipShown=true;try{if(localStorage.getItem(AUTO_INTRO)==='done')return}catch(_){}startTour('automation')}
function showRateDetails(){
 const raw=state.rawProduction(),board=state.boardStats(),finalRate=state.production(),stellar=state.cosmos.stars.length+state.cosmos.planets.length;
 const w=state.workshop,autoSpeed=w.stage>=2&&w.autoTapOn?(w.stage>=5?3:w.stage>=4?2:w.stage>=3?1.2:.6):0;
 const workshopBase=H.from(board.output);const starFactor=state.stellarMultiplier();
 modal(`<span class="eyebrow">生産の仕組み</span><h2 id="modal-title">どこから増えている？</h2><p>毎秒の生産量は、設備・工房・天体・研究などの効果によって決まります。数字が変わった理由をここで確認できます。</p>
 <dl class="rate-audit"><div><dt>設備の基礎出力</dt><dd>${fmt(raw)} E/秒</dd></div><div><dt>創造盤の基礎出力</dt><dd>${fmt(workshopBase)} E/秒</dd></div><div><dt>装置の発熱</dt><dd>${board.heat}（稼働効率 ${Math.round(board.eff*100)}%）</dd></div><div><dt>天体の生産倍率</dt><dd>×${Number(starFactor.toPrecision(4)).toLocaleString('ja-JP')} <small>天体 ${stellar} 個</small></dd></div><div class="rate-result"><dt>補正を含む設備生産</dt><dd>${fmt(finalRate)} E/秒</dd></div><div><dt>自動点火（別枠）</dt><dd>${autoSpeed?fmt(state.tapPower().mul(autoSpeed))+' E/秒':'停止中'}</dd></div></dl>
 <p class="rate-audit-note">転生・研究・実績・星図・運転方針・法則の倍率や指数補正は、最終生産量に含まれます。自動点火は「設備生産」とは別に加算されます。</p>
 <div class="modal-actions"><button class="action secondary" data-action="close-modal">閉じる</button></div>`,'rate');
}
function showSettings(){modal(`<span class="eyebrow">SETTINGS / 設定</span><h2 id="modal-title">設定とセーブ</h2>${renderSettings()}<div class="modal-actions"><button class="action secondary" data-action="close-modal">閉じる</button></div>`,'settings')}
function showPrestigeConfirm(tier){const p=state.previewPrestige(tier);if(!p.ready)return;
 modal(`<span class="eyebrow">T${tier} · 共通の転生</span><h2 id="modal-title">T${tier}を完了して、最初から始めますか？</h2><p><strong>すべての保有通貨、設備、研究、スキル、建設中の装置と天体を初期化します。</strong></p><p><strong>残るもの：</strong>これまでに習得した作業、設計図、レシピ、自動化、実績、転生履歴と永続倍率。</p><p>今回の達成評価：${fmt(p.reward)}（永続倍率に少し反映されます）。<strong>転生通貨そのものは持ち越されません。</strong></p><p class="cycle-modal-promise">次周の永続生産倍率：<strong>×${fmt(H.from(state.nextCycleMultiplier(tier)))}</strong>。以前突破した階層は再建して順番に復帰できます。</p><div class="modal-actions"><button class="action secondary" data-action="close-modal">戻る</button><button class="action" data-confirm-prestige="${tier}">T${tier}を完了する</button></div>`,'confirm');
}
function toggleFocus(force){let yes=typeof force==='boolean'?force:!document.body.classList.contains('focus-mode');document.body.classList.toggle('focus-mode',yes);let b=$('focus-toggle');b.setAttribute('aria-pressed',String(yes));b.textContent=yes?'↙ 通常表示':'◈ 没入表示';}
function goto(where){
 if(document.body.classList.contains('focus-mode'))toggleFocus(false);
 if(where!=='core'&&where!=='equipment'&&!getAvailable()[where])where='guide';
 document.body.dataset.mobileView=where;
 if(where!=='core'&&where!=='equipment'){tab=where;renderPanel()}
 document.querySelectorAll('.mobile-nav [data-mobile]').forEach(e=>{
  let selected=e.dataset.mobile===where;e.classList.toggle('active',selected);
  if(selected)e.setAttribute('aria-current','page');else e.removeAttribute('aria-current')
 });
 const menuButton=document.querySelector('.mobile-nav [data-action="feature-menu"]');
 menuButton?.classList.toggle('active',!['core','equipment','automation','achievements'].includes(where));
 if(tourActive){requestAnimationFrame(()=>window.scrollTo({top:0,behavior:'instant'}))}else window.scrollTo({top:0,behavior:'instant'});
}
function handleAction(action,b){switch(action){case 'close-modal':closeModal();break;case 'open-rebuild':goto('prestige');break;
 case 'reconstruct-tier':if(state.reconstructTier()){render();save();note('習得済みのT'+state.state.unlockedTier+'を再建しました。次の階層の準備を進めましょう。')}break;
 case 'toggle-auto-rebuild':state.setAutoRebuild(Boolean(b.checked));render();save();break;
 case 'migrate-old-cycle':modal(`<h2 id="modal-title">新しい転生ルールに切り替えますか？</h2><p>今の階層までの到達記録を引き継ぎ、T0から始めます。追加の通貨・倍率は付与されません。現在の設備・資源は初期化されます。</p><div class="modal-actions"><button class="action secondary" data-action="close-modal">戻る</button><button class="action" data-action="confirm-migrate-old-cycle">T0へ切り替える</button></div>`,'confirm');break;
 case 'confirm-migrate-old-cycle':if(state.migrateOldRun()){closeModal();render();save();note('旧セーブを新しい転生ルールへ移行しました。')}break;
 case 'start-bridge':if(state.startBridge()){note('演算橋が稼働を開始しました。時間とともに数値階層を突破します。');render();save()}break;case 'ascend-endless':if(state.ascendEndless()){note('永続創世ランクが上がりました！');render();save()}break;case 'abandon-challenge':if(confirm('試練を中止しますか？')){state.finishChallenge(true);render();save()}break;case 'exit-extra-mini':extraMini=null;renderPanel();break;case 'start-circuit':if(state.state.miniCharges>0){initializeCircuit();renderPanel()}break;case 'reset':if(confirm('新しいゲームを始めますか？ 現在の進行をバックアップに退避します（設定から復元可能）。')){try{localStorage.setItem(SAVE+'_backup',JSON.stringify(state.snapshot()))}catch(err){note('バックアップの保存に失敗しました。手動で書き出してからやり直してください。');break}state=new ForgeEngine(window.FORGE_DATA);window.ForgeScore?.enable(false);window.ForgeImmersion?.reset();save();tab='guide';lastMission=-1;render();closeModal();note('最初から始めます。')}break;}}
function events(){window.addEventListener('pagehide',()=>save());document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')save()});window.addEventListener('resize',()=>{if(tourActive)requestAnimationFrame(placeTour)},{passive:true});window.addEventListener('scroll',()=>{if(tourActive)requestAnimationFrame(placeTour)},{passive:true});document.addEventListener('click',ev=>{let b=ev.target.closest('button,input[data-action="toggle-auto-rebuild"],[data-action="close-modal"]');if(!b)return;if(b.id==='core'){if(!$('overlay').hidden)return;let before=state.workshop.stage;state.manualTap();if(state.workshop.stage!==before){updateVisibility(true);renderPanel();if(state.workshop.stage>=2&&!tourActive)checkAutomationTour()}flash();renderTop();renderMission();if(state.state.taps<=30||performance.now()-lastFacilityAt>450)renderFacilities();return}if(b.dataset.petPull!==undefined){const n=Number(b.dataset.petPull),result=state.petPull(n);if(result){render();save();showPetResults(result)}else note('エネルギーが不足しています。');return}if(b.dataset.petMergeAll!==undefined){const rank=Number(b.dataset.petMergeAll),plus=Number(b.dataset.petPlus||0),n=state.petMergeAll(rank,plus);if(n){render();save();note(n+'回分をまとめて合成しました。')}else note('同じランクのペットが5体必要です。');return}if(b.dataset.petMerge!==undefined){const rank=Number(b.dataset.petMerge),plus=Number(b.dataset.petPlus||0);if(state.petMerge(rank,plus)){render();save();note('5体を合成して、上のランクのペットを獲得しました。')}else note('同じランクのペットが5体必要です。');return}if(b.dataset.petRebirth!==undefined){if(state.petCollection().unlocked){showPetRebirthConfirm()}return}if(b.dataset.petConfirm!==undefined){if(state.petRebirth()){closeModal();render();save();note('ペット転生が完了しました。次の仲間の効果がさらに2倍になります。')}return}if(b.dataset.tierWork!==undefined){const t=Number(b.dataset.tierWork);if(state.performTierTask(t,b.dataset.choice)){render();save();note('作業を記録しました。強化と次の習得条件が更新されました。')}else note('資源不足か、選択した強化が上限に達しています。');return}if(b.dataset.achView){achievementsView=b.dataset.achView;renderPanel();return}if(b.dataset.workPiece){state.workshop.selected=b.dataset.workPiece;renderPanel();return}
 if(b.dataset.workCell!==undefined){let index=Number(b.dataset.workCell),type=state.workshop.selected,prev=state.workshop.stage;if(state.manualPlace(index,type)){render();save();if(state.workshop.stage>prev){note('新しい工程「'+window.ForgeWorkshopData.stages[state.workshop.stage].name+'」を習得しました');if(state.workshop.stage>=2)checkAutomationTour();}}else note('配置先が埋まっている場合は、先に「撤去」を選んでください。必要な材料も確認してください。');return}
 if(b.dataset.workCraft){let prev=state.workshop.stage;if(state.manualCraft(b.dataset.workCraft)){render();save();if(state.workshop.stage>prev)note('新しい工程を習得しました')}else note('素材かエネルギーが不足しています。');return}
 if(b.dataset.procurement){if(state.changeProcurement(b.dataset.procurement)){renderPanel();save();note('自動購入の方針を変更しました')}return}
 if(b.dataset.blueprintSlot!==undefined){state.selectBlueprint(Number(b.dataset.blueprintSlot));renderPanel();save();return}
 if(b.hasAttribute('data-blueprint-save')){let oldPlan=state.workshop.blueprints[state.workshop.activeBlueprint];if(oldPlan&&JSON.stringify(oldPlan)!==JSON.stringify(state.workshop.board)&&!confirm('この設計図を現在の盤面で上書きしますか？ 保存済みの配置は戻せません。'))return;if(state.recordBlueprint()){note('現在の配置を設計図に保存しました。自動化タブから盤面整備を稼働できます。');renderPanel();save()}else note('装置をひとつ以上配置してから保存してください。');return}
 if(b.hasAttribute('data-blueprint-clear')){if(confirm('選択中の設計図を消去しますか？ 現在の盤面は変わりません。')&&state.clearBlueprint()){note('設計図を消去しました。自動配置を停止しました。');renderPanel();save()}return}
 if(b.dataset.workToggle){let name=b.dataset.workToggle;if(['autoTapOn','autoBuyOn','autoCraftOn','autoLayoutOn','autoPrestigeOn'].includes(name)){if(name==='autoLayoutOn'&&!state.workshop.autoLayoutOn&&!state.blueprintInfo().saved){note('盤面の自動化には、工房で設計図を保存する必要があります。');goto('workshop');return}if(name==='autoPrestigeOn'&&!state.workshop.autoPrestigeOn&&!confirm('自動転生を有効にしますか？ 設定した階層の条件を満たすと、すべての保有資源・設備・工房盤面が自動で初期化されます。'))return;state.workshop[name]=!state.workshop[name];renderPanel();save()}return}
 if(b.dataset.confirmPrestige){if(state.manualPrestige(Number(b.dataset.confirmPrestige))){const finishedTier=Number(b.dataset.confirmPrestige);window.ForgeImmersion?.prestige(Number(b.dataset.confirmPrestige));skillTierView=Math.max(1,Math.min(14,state.state.unlockedTier));researchTierView=Math.min(11,state.state.unlockedTier);closeModal();note('T'+finishedTier+'を完了。T0へ戻りました。過去に覚えた作業と倍率は引き継いでいます。');render();save()}return}if(b.dataset.explore){if(state.explore(b.dataset.explore)){note('星図を調査しました。文明知識を獲得！');render();save()}return}if(b.dataset.civ){if(state.trainCiv(b.dataset.civ)){note('文明が発展しました！');render();save()}return}if(b.dataset.law){if(state.toggleLaw(b.dataset.law)){note('宇宙の法則を更新しました。');render();save()}return}if(b.dataset.challenge){if(state.startChallenge(b.dataset.challenge)){note('試練を開始しました。条件を満たすと自動クリア！');render();save()}return}if(b.dataset.claimConstellation){if(state.claimConstellation(b.dataset.claimConstellation)){note('星図の記録が完成！ 恒久生産倍率 ×1.04');render();save()}return}if(b.dataset.signalPad!==undefined){signalPress(Number(b.dataset.signalPad));return}if(b.dataset.extraMini){if(startExtraMini(b.dataset.extraMini))renderPanel();return}if(b.dataset.extraAnswer!==undefined){answerExtraMini(Number(b.dataset.extraAnswer));return}if(b.dataset.circuit!==undefined){circuitRotate(Number(b.dataset.circuit));return}if(b.dataset.buy){let prevStage=state.workshop.stage;let count=state.manualBuy(b.dataset.buy,buyMode==='max'?'max':buyMode==='milestone'?([10,25,50,100,250,1000].find(x=>x>state.owned(b.dataset.buy))||state.owned(b.dataset.buy)+1)-state.owned(b.dataset.buy):Number(buyMode));if(count){window.ForgeImmersion?.purchase(b.dataset.buy,count);render();if(state.workshop.stage>prevStage)note('手作業を習得しました。自動化タブを確認してください');if(state.owned('E01')===count&&b.dataset.buy==='E01')note('粒子抽出器が稼働！ 基本性能は毎秒+1です。現在の生産量は上の表示で確認できます。')}return}if(b.dataset.research){if(state.buyResearch(b.dataset.research)){window.ForgeImmersion?.research();note('研究が完成しました！ 生産が強化されます。')}render();return}if(b.dataset.skill){if(state.buySkill(b.dataset.skill)){window.ForgeImmersion?.skill();note('新しいスキルを取得しました！');}render();return}if(b.dataset.prestige){showPrestigeConfirm(Number(b.dataset.prestige));return}if(b.dataset.tab){goto(b.dataset.tab);return}if(b.dataset.mini){if(!mini.running){mini={running:true,round:0,hits:[],start:performance.now()};tab='mini';renderPanel()}else miniStop();return}if(b.dataset.mobile){goto(b.dataset.mobile);return}if(b.dataset.action)handleAction(b.dataset.action,b)});
$('buy-mode').addEventListener('change',e=>{buyMode=e.target.value;renderFacilities()});document.addEventListener('change',e=>{if(e.target.id==='auto-prestige-target'){state.workshop.autoPrestigeTarget=Number(e.target.value);save();renderPanel()}if(e.target.id==='research-tier-filter'){researchTierView=Number(e.target.value);renderPanel()}if(e.target.id==='skill-tier-filter'){skillTierView=Number(e.target.value);renderPanel()}if(e.target.id==='auto-policy'){state.setAutoPolicy(e.target.value);save()}if(e.target.id==='focus-mode'){state.state.settings.focusMode=e.target.value;render();save();note('運転方針を変更しました')}if(e.target.id==='number-format'){state.state.settings.numberFormat=e.target.value;render();save();showSettings()}if(e.target.id==='text-size'){state.state.settings.textSize=e.target.value;applyPreferences();save();showSettings()}});$('import-file').addEventListener('change',e=>{importSave(e.target.files[0]);e.target.value=''});
document.addEventListener('change',e=>{if(e.target.dataset.tierPreference!==undefined){if(state.setTierWorkPreference(Number(e.target.dataset.tierPreference),e.target.value)){renderPanel();save();note('自動作業の方針を変更しました。')}return}if(e.target.dataset.tierToggle!==undefined){state.setTierWorkAuto(Number(e.target.dataset.tierToggle),e.target.checked);renderPanel();save()}if(e.target.id==='auto-buy')state.setAuto('buy',e.target.checked);if(e.target.id==='auto-rebirth')state.setAuto('rebirth',e.target.checked);if(e.target.id==='reduced-effects'){state.state.settings.effects=!e.target.checked;applyPreferences();save();}if(e.target.id==='high-contrast'){state.state.settings.contrast=e.target.checked;applyPreferences();save();}if(e.target.id==='sound-setting'){window.ForgeImmersion?.audio(e.target.checked);save();}});
document.addEventListener('keydown',e=>{if(signal.active&&tab==='mini'&&signal.phase==='input'&&['Digit1','Digit2','Digit3','Digit4'].includes(e.code)&&$('overlay').hidden){e.preventDefault();signalPress(Number(e.code.slice(-1))-1);return}if(!$('overlay').hidden&&e.key==='Tab'){const focusable=[...$('overlay').querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),a[href]')].filter(x=>x.getClientRects().length);if(focusable.length){const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}return}if(e.altKey&&!e.repeat&&['Digit1','Digit2','Digit3'].includes(e.code)&&$('overlay').hidden){e.preventDefault();goto(({Digit1:'core',Digit2:'equipment',Digit3:'guide'})[e.code]);return}if(e.code==='Escape'&&document.body.classList.contains('focus-mode')&&$('overlay').hidden){toggleFocus(false);return}if(e.code==='Escape'&&tourActive){finishTour();return}if(e.code==='Escape'&&!$('overlay').hidden){if(modalMode==='intro')completeIntro();else closeModal();return}if(e.code==='Space'&&!e.repeat&&!['INPUT','SELECT','TEXTAREA','BUTTON'].includes(document.activeElement?.tagName)&&$('overlay').hidden){e.preventDefault();if(mini.running)miniStop();else{let before=state.workshop.stage;state.manualTap();if(state.workshop.stage>before){render();if(state.workshop.stage>=2)checkAutomationTour()}flash();renderTop();renderMission()}}});window.addEventListener('beforeunload',save);document.addEventListener('visibilitychange',()=>{if(document.hidden)save()});}
function main(){let resumed=restore();window.ForgeGameAPI={getEngine:()=>state,render:()=>render(),goto:id=>goto(id),save:()=>save(),note:msg=>note(msg)};window.ForgeScore?.init(()=>state);skillTierView=Math.min(14,Math.max(1,state.state.unlockedTier));researchTierView=Math.min(11,state.state.unlockedTier);window.ForgeImmersion?.init(()=>state);events();updateVisibility(false);render();suppressMissionMessage=false;applyPreferences();if(resumed){autoTipShown=state.workshop.stage>=2}if(!resumed){let skip=false;try{skip=localStorage.getItem(INTRO)==='done'}catch(e){}if(!skip)showIntro()}let last=performance.now(),lastFullRender=last,lastSave=last,hiddenAt=null;
function loop(){let now=performance.now();if(!document.hidden){let dt=Math.max(0,Math.min(2,(now-last)/1000));last=now;state.tick(dt);renderTop();if(now-lastFullRender>=2500){render(false);lastFullRender=now}if(now-lastPanelRenderAt>=8000&&!tourActive){const focused=document.activeElement;if(!focused||!$('side-content').contains(focused)||!['INPUT','SELECT','TEXTAREA'].includes(focused.tagName)){renderPanel();lastPanelRenderAt=now}}if(now-lastSave>=12000){save();lastSave=now}}else{last=now}setTimeout(loop,document.hidden?1000:refreshInterval(state.production()))}
document.addEventListener('visibilitychange',()=>{if(document.hidden){hiddenAt=Date.now();save()}else{if(hiddenAt!==null){const elapsed=Math.max(0,(Date.now()-hiddenAt)/1000);if(elapsed>=1){state.offline(elapsed);render();if(elapsed>=15)note('離れている間の生産を60%の効率で反映しました')}hiddenAt=null}last=performance.now()}});
setTimeout(loop,refreshInterval(state.production()));/* mini-game visuals are retired. No perpetual animation loop is needed. */}
main();
if('serviceWorker' in navigator&&location.protocol!=='file:'&&location.protocol!=='about:')navigator.serviceWorker.register('./sw.js').catch(()=>{});
